insert into public.training_knowledge(id,kind,version,content) values('spacing','reference','2026-10-10.1','{"id":"spacing","title":"Mind the gap: Distributed practice enhances performance in a MOBA game","url":"https://pubmed.ncbi.nlm.nih.gov/36240151/","kind":"scientific","access":"abstract","published_at":"2022-10-14","verified_at":"2026-10-10","claim":"Dados observacionais de 162.417 jogadores de League of Legends associaram prática distribuída a melhor desempenho.","limitations":"Associação não demonstra causalidade. Outro jogo; não determina uma dose de treino para Fortnite."}'::jsonb) on conflict(kind,id) do nothing;
insert into public.training_knowledge(id,kind,version,content) values('motor-review','reference','2026-10-10.1','{"id":"motor-review","title":"Skill acquisition interventions for the learning of sports-related skills","url":"https://pubmed.ncbi.nlm.nih.gov/38401870/","kind":"scientific","access":"abstract","published_at":"2024-02-23","verified_at":"2026-10-10","claim":"Revisão de escopo de 130 estudos controlados identifica concentração em iniciantes e tarefas fechadas; testes de transferência são menos frequentes.","limitations":"Esportes convencionais; limitações de amostra, viés e acompanhamento curto restringem extrapolação para decisões em Fortnite."}'::jsonb) on conflict(kind,id) do nothing;
insert into public.training_knowledge(id,kind,version,content) values('exercise-review','reference','2026-10-10.1','{"id":"exercise-review","title":"Effects of Acute and Chronic Physical Exercise on Esports Performance: A Systematic Review","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC13197565/","kind":"scientific","access":"text_sections","published_at":"2026-05-23","verified_at":"2026-10-10","claim":"Revisão de 12 estudos experimentais encontrou benefícios agudos em alguns desfechos; os resultados crônicos foram mistos.","limitations":"PMID 42174296. Intervenções e medidas heterogêneas; não valida prescrição de exercício nem melhoria específica em Fortnite."}'::jsonb) on conflict(kind,id) do nothing;
insert into public.training_knowledge(id,kind,version,content) values('variability','reference','2026-10-10.1','{"id":"variability","title":"The effect of contextual interference on transfer in motor learning","url":"https://pubmed.ncbi.nlm.nih.gov/39205981/","kind":"scientific","access":"abstract","published_at":"2024-08-14","verified_at":"2026-10-10","claim":"Meta-análise encontrou benefício agregado da prática aleatória na transferência, com diferenças entre contexto laboratorial, aplicado e faixas etárias.","limitations":"Efeito aplicado não significativo e pequeno em jovens; alternar tarefas não é uma regra universal, sobretudo para iniciantes."}'::jsonb) on conflict(kind,id) do nothing;
insert into public.training_knowledge(id,kind,version,content) values('attention-bias','reference','2026-10-10.1','{"id":"attention-bias","title":"Reporting bias, not external focus","url":"https://pubmed.ncbi.nlm.nih.gov/39480294/","kind":"scientific","access":"abstract","published_at":"2024-11","verified_at":"2026-10-10","claim":"Reanálise com modelos de viés de publicação encontrou efeitos médios pequenos ou desprezíveis do foco externo e heterogeneidade.","limitations":"Contradiz uma recomendação universal; não prova que todas as pistas de atenção sejam equivalentes para cada tarefa."}'::jsonb) on conflict(kind,id) do nothing;
insert into public.training_knowledge(id,kind,version,content) values('sleep','reference','2026-10-10.1','{"id":"sleep","title":"CDC — About Sleep","url":"https://www.cdc.gov/sleep/about/index.html","kind":"official","access":"page","published_at":"2024-05-15","verified_at":"2026-10-10","claim":"A orientação de saúde pública distingue necessidades por idade e considera tanto qualidade quanto duração do sono.","limitations":"Informação geral de saúde; não é um protocolo competitivo individual nem promessa de desempenho."}'::jsonb) on conflict(kind,id) do nothing;
insert into public.training_knowledge(id,kind,version,content) values('ergonomics','reference','2026-10-10.1','{"id":"ergonomics","title":"OSHA — Computer Workstations: Good Working Positions","url":"https://www.osha.gov/etools/computer-workstations/positions","kind":"official","access":"page","published_at":null,"verified_at":"2026-10-10","claim":"Orientações de trabalho ao computador incluem postura confortável, apoio e mudança de posição ao longo do dia.","limitations":"Não estabelece pegada, sensibilidade ou postura universal para esports; desconforto não deve ser tratado como requisito de prática."}'::jsonb) on conflict(kind,id) do nothing;
insert into public.training_knowledge(id,kind,version,content) values('khanada','reference','2026-10-10.1','{"id":"khanada","title":"How Fortnite Pros Actually Practice in 2026, Featuring Khanada","url":"https://dignitas.gg/articles/how-fortnite-pros-actually-practice-in-2026-featuring-khanada","kind":"professional","access":"page","published_at":"2026-09-11","verified_at":"2026-10-10","claim":"Na entrevista, Khanada descreve aquecimento, prática competitiva e revisão de partidas; destaca compreensão do jogo e scrims para desenvolvimento.","limitations":"Relato de um jogador selecionado. Não representa todos os profissionais nem demonstra causalidade ou duração ideal."}'::jsonb) on conflict(kind,id) do nothing;
