insert into public.training_knowledge(id,kind,version,content) values('editorial','reference','2026-10-10.1','{"id":"editorial","title":"Metodologia Clutchfolio — versão 1","url":"https://github.com/sallumm/fortnite-competitive-platform/blob/feat/training-research/docs/research/TRAINING_METHODOLOGY.md","kind":"editorial","access":"original","published_at":"2026-10-10","verified_at":"2026-10-10","claim":"Ciclo de observar, escolher uma habilidade, praticar, aplicar, revisar e reavaliar com condições comparáveis.","limitations":"Proposta editorial informada por referências heterogêneas; ainda não validada como intervenção em Fortnite."}'::jsonb) on conflict(kind,id) do nothing;
