insert into public.training_knowledge(id,kind,version,content) values('fatigue','reference','2026-10-10.1','{"id":"fatigue","title":"Beyond Performance: Cognitive Overload and Related States in Competitive Esports","url":"https://pubmed.ncbi.nlm.nih.gov/42506364/","kind":"scientific","access":"abstract","published_at":"2026-07-15","verified_at":"2026-10-10","claim":"Revisão de escopo de 48 estudos identifica definições e medidas heterogêneas de carga, estresse, fadiga e desempenho em esports.","limitations":"Esses estados não são intercambiáveis. Um resultado baixo ou uma autoavaliação isolada não permite diagnosticar fadiga."}'::jsonb) on conflict(kind,id) do nothing;
insert into public.training_knowledge(id,kind,version,content) values('veno-description','reference','2026-10-10.1','{"id":"veno-description","title":"No Mobility Midgame Meta with Veno — DestinysJesus","url":"https://www.fortnitemasterclass.com/p/courses/solos-masterclass/3017695-how-to-become-a-200-iq-player/4372460-no-mobility-midgame-meta-with-veno","kind":"professional","access":"metadata","published_at":null,"verified_at":"2026-10-10","claim":"A descrição pública apresenta uma revisão de posicionamento e rotações em uma sessão de Veno sem mobilidade.","limitations":"Somente descrição consultada. Vídeo não assistido, curso não adquirido e temporada não confirmada; não é orientação sobre o meta atual."}'::jsonb) on conflict(kind,id) do nothing;
insert into public.training_knowledge(id,kind,version,content) values('deliberate-meta','reference','2026-10-10.1','{"id":"deliberate-meta","title":"The Relationship Between Deliberate Practice and Performance in Sports","url":"https://journals.sagepub.com/doi/10.1177/1745691616635591","kind":"scientific","access":"abstract","published_at":"2016-05-22","verified_at":"2026-10-10","claim":"A meta-análise relaciona prática e desempenho esportivo, mas encontra variação por nível e participação de outros fatores.","limitations":"Associações e definições de prática não demonstram causalidade nem estabelecem uma regra de horas. Debate conceitual com Ericsson."}'::jsonb) on conflict(kind,id) do nothing;
insert into public.training_knowledge(id,kind,version,content) values('deliberate-debate','reference','2026-10-10.1','{"id":"deliberate-debate","title":"Summing Up Hours of Any Type of Practice Versus Identifying Optimal Practice Activities","url":"https://www.psychologicalscience.org/journals/perspectives/1745691616635600/","kind":"scientific","access":"abstract","published_at":"2016-05","verified_at":"2026-10-10","claim":"Ericsson questiona agrupar horas de atividades distintas e destaca objetivos definidos e feedback informativo na conceituação de prática deliberada.","limitations":"Comentário científico, não ensaio experimental. Discordância sobre definição impede tratar contagem de horas como explicação completa da expertise."}'::jsonb) on conflict(kind,id) do nothing;
insert into public.training_knowledge(id,kind,version,content) values('perception','reference','2026-10-10.1','{"id":"perception","title":"Effects of Perceptual-Cognitive Training on Anticipation and Decision-Making Skills in Team Sports","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC11505547/","kind":"scientific","access":"indexed_excerpt","published_at":"2024-10-09","verified_at":"2026-10-10","claim":"O trecho indexado da revisão distingue efeitos em tarefas de laboratório e transferência para o esporte, com efeitos menores na transferência.","limitations":"Texto completo bloqueado na consulta; apenas trecho primário indexado. Esportes coletivos, não Fortnite. Não valida o protocolo de pausa de VOD do produto."}'::jsonb) on conflict(kind,id) do nothing;
insert into public.training_knowledge(id,kind,version,content) values('feedback-children','reference','2026-10-10.1','{"id":"feedback-children","title":"How can instructions and feedback with external focus be shaped to enhance motor learning in children?","url":"https://pubmed.ncbi.nlm.nih.gov/36007080/","kind":"scientific","access":"indexed_excerpt","published_at":"2022","verified_at":"2026-10-10","claim":"O resumo indexado informa heterogeneidade e dados incompletos, levando a síntese de melhor evidência em vez de uma prescrição única de feedback.","limitations":"Trecho de resumo, crianças e tarefas motoras amplas. Não define frequência ideal de feedback em esports nem substitui supervisão adequada."}'::jsonb) on conflict(kind,id) do nothing;
