insert into public.training_knowledge(id,kind,version,content) values('offspawn','competency','2026-10-10.1','{"id":"offspawn","category":"combat","subcategory":"Queda","title":"Off-spawn","mode":"both","definition":"Decidir com loot e informação limitados logo após a queda.","context":"Disputa inicial por área e recursos.","example":"Registrar a rota de saída disponível antes de aceitar a luta.","evidence_ids":["editorial"],"classification":"editorial"}'::jsonb) on conflict(kind,id) do nothing;
insert into public.training_knowledge(id,kind,version,content) values('positioning','competency','2026-10-10.1','{"id":"positioning","category":"decisions","subcategory":"Leitura espacial","title":"Posicionamento","mode":"both","definition":"Escolher onde ficar considerando informação, cobertura e próximos movimentos.","context":"Antes de uma luta ou mudança de zona.","example":"Comparar duas posições usando apenas informação disponível naquele momento.","evidence_ids":["editorial"],"classification":"editorial"}'::jsonb) on conflict(kind,id) do nothing;
insert into public.training_knowledge(id,kind,version,content) values('fight-selection','competency','2026-10-10.1','{"id":"fight-selection","category":"decisions","subcategory":"Decisão","title":"Escolha de confrontos","mode":"both","definition":"Avaliar se iniciar, prolongar ou evitar uma luta serve ao objetivo.","context":"Gestão de risco de uma partida.","example":"Revisar um confronto opcional antes de observar seu resultado.","evidence_ids":["editorial"],"classification":"editorial"}'::jsonb) on conflict(kind,id) do nothing;
insert into public.training_knowledge(id,kind,version,content) values('rotation','competency','2026-10-10.1','{"id":"rotation","category":"decisions","subcategory":"Deslocamento","title":"Rotação","mode":"both","definition":"Planejar e ajustar o deslocamento entre posições úteis.","context":"Mudanças de zona e pressão adversária.","example":"Anotar cobertura, tempo e ameaça conhecida em duas rotas.","evidence_ids":["editorial"],"classification":"editorial"}'::jsonb) on conflict(kind,id) do nothing;
insert into public.training_knowledge(id,kind,version,content) values('deadside','competency','2026-10-10.1','{"id":"deadside","category":"decisions","subcategory":"Leitura espacial","title":"Deadside","mode":"both","definition":"Lado com menor concentração observável de jogadores.","context":"Escolha de rotação.","example":"Tratar a baixa presença como informação parcial, não garantia de segurança.","evidence_ids":["editorial"],"classification":"editorial"}'::jsonb) on conflict(kind,id) do nothing;
insert into public.training_knowledge(id,kind,version,content) values('resources','competency','2026-10-10.1','{"id":"resources","category":"decisions","subcategory":"Recursos","title":"Gestão de recursos","mode":"both","definition":"Decidir como usar vida, munição, mobilidade e recursos disponíveis.","context":"Preparação para movimentos ou lutas.","example":"Registrar o recurso necessário que faltou na decisão seguinte.","evidence_ids":["editorial"],"classification":"editorial"}'::jsonb) on conflict(kind,id) do nothing;
insert into public.training_knowledge(id,kind,version,content) values('information','competency','2026-10-10.1','{"id":"information","category":"decisions","subcategory":"Leitura da partida","title":"Noção de Jogo","mode":"both","definition":"Integrar informação observada, riscos e objetivos para decidir.","context":"Ao longo de toda a partida.","example":"Separar o que era conhecido do que só o replay revelou.","evidence_ids":["editorial"],"classification":"editorial"}'::jsonb) on conflict(kind,id) do nothing;
insert into public.training_knowledge(id,kind,version,content) values('zone-wars','competency','2026-10-10.1','{"id":"zone-wars","category":"endgame","subcategory":"Simulação","title":"Zone Wars","mode":"build","definition":"Praticar situações de zona móvel em uma ilha configurada para isso.","context":"Aplicação parcial de decisões de fim de partida.","example":"Registrar regras da ilha e evitar equiparar o resultado a uma final.","evidence_ids":["editorial"],"classification":"editorial"}'::jsonb) on conflict(kind,id) do nothing;
insert into public.training_knowledge(id,kind,version,content) values('tarping','competency','2026-10-10.1','{"id":"tarping","category":"endgame","subcategory":"Proteção","title":"Tarpar / Tarping","mode":"build","definition":"Avançar construindo um caminho de proteção.","context":"Movimentação sob pressão na zona.","example":"Revisar falhas de cobertura e materiais consumidos.","evidence_ids":["editorial"],"classification":"editorial"}'::jsonb) on conflict(kind,id) do nothing;
insert into public.training_knowledge(id,kind,version,content) values('refresh','competency','2026-10-10.1','{"id":"refresh","category":"endgame","subcategory":"Recursos","title":"Refresh","mode":"build","definition":"Buscar recursos por uma oportunidade de combate ou coleta no fim da partida.","context":"Recursos escassos em endgame.","example":"Comparar risco da luta com alternativas de continuar a rotação.","evidence_ids":["editorial"],"classification":"editorial"}'::jsonb) on conflict(kind,id) do nothing;
insert into public.training_knowledge(id,kind,version,content) values('layers','competency','2026-10-10.1','{"id":"layers","category":"endgame","subcategory":"Posicionamento","title":"Layers / camadas","mode":"build","definition":"Escolher e mudar a altura relativa aos outros jogadores.","context":"Zona móvel com múltiplos níveis.","example":"Revisar congestionamento, cobertura e recursos ao trocar de camada.","evidence_ids":["editorial"],"classification":"editorial"}'::jsonb) on conflict(kind,id) do nothing;
insert into public.training_knowledge(id,kind,version,content) values('moving-zone','competency','2026-10-10.1','{"id":"moving-zone","category":"endgame","subcategory":"Leitura coletiva","title":"Leitura de zona móvel","mode":"both","definition":"Ajustar deslocamento à zona e às rotas coletivas observáveis.","context":"Fim de partida em movimento.","example":"Anotar uma mudança de direção e a informação usada para reagir.","evidence_ids":["editorial"],"classification":"editorial"}'::jsonb) on conflict(kind,id) do nothing;
insert into public.training_knowledge(id,kind,version,content) values('surge','competency','2026-10-10.1','{"id":"surge","category":"competitive","subcategory":"Regras e dano","title":"Storm Surge","mode":"build","definition":"Planejar janelas de dano quando a competição utiliza a mecânica correspondente.","context":"Partidas com muitos jogadores vivos.","example":"Consultar regras atuais antes de analisar necessidade de dano; não fixar limites antigos.","evidence_ids":["editorial"],"classification":"editorial"}'::jsonb) on conflict(kind,id) do nothing;
insert into public.training_knowledge(id,kind,version,content) values('scrims','competency','2026-10-10.1','{"id":"scrims","category":"competitive","subcategory":"Prática organizada","title":"Scrims","mode":"both","definition":"Partidas de treinamento organizadas por uma comunidade ou grupo.","context":"Praticar objetivos coletivos e situações competitivas.","example":"Registrar regras da sala e revisar uma rotação; regras de scrim podem diferir do torneio.","evidence_ids":["editorial"],"classification":"editorial"}'::jsonb) on conflict(kind,id) do nothing;
insert into public.training_knowledge(id,kind,version,content) values('ranked','competency','2026-10-10.1','{"id":"ranked","category":"competitive","subcategory":"Partida oficial","title":"Ranqueada / Ranked","mode":"both","definition":"Aplicar um objetivo em partidas do modo ranqueado disponível.","context":"Prática contextual com oposição.","example":"Revisar a decisão escolhida, sem usar variação de rank como medida isolada da habilidade.","evidence_ids":["editorial"],"classification":"editorial"}'::jsonb) on conflict(kind,id) do nothing;
insert into public.training_knowledge(id,kind,version,content) values('tournament-prep','competency','2026-10-10.1','{"id":"tournament-prep","category":"competitive","subcategory":"Preparação","title":"Preparação para torneio","mode":"both","definition":"Conferir regras, requisitos, agenda e objetivos antes de competir.","context":"Semana competitiva.","example":"Validar fase, modalidade e horário na fonte oficial antes de agendar.","evidence_ids":["editorial"],"classification":"editorial"}'::jsonb) on conflict(kind,id) do nothing;
insert into public.training_knowledge(id,kind,version,content) values('self-review','competency','2026-10-10.1','{"id":"self-review","category":"vod","subcategory":"Análise própria","title":"VOD Review próprio","mode":"both","definition":"Revisar a própria gravação para reconstruir decisões e padrões.","context":"Após uma sessão ou erro recorrente.","example":"Pausar antes da decisão e escrever uma alternativa testável.","evidence_ids":["editorial"],"classification":"editorial"}'::jsonb) on conflict(kind,id) do nothing;
insert into public.training_knowledge(id,kind,version,content) values('pro-review','competency','2026-10-10.1','{"id":"pro-review","category":"vod","subcategory":"Análise externa","title":"VOD Review de profissional","mode":"both","definition":"Estudar decisões de outro jogador considerando seu contexto e informação.","context":"Explorar alternativas.","example":"Registrar timestamp e contexto; não copiar uma decisão só por vir de um campeão.","evidence_ids":["editorial"],"classification":"editorial"}'::jsonb) on conflict(kind,id) do nothing;
insert into public.training_knowledge(id,kind,version,content) values('pattern-review','competency','2026-10-10.1','{"id":"pattern-review","category":"vod","subcategory":"Feedback","title":"Identificação de padrões","mode":"both","definition":"Comparar episódios para verificar se uma dificuldade reaparece.","context":"Revisão de várias sessões.","example":"Contar exemplos e contraexemplos antes de chamar um erro de recorrente.","evidence_ids":["editorial"],"classification":"editorial"}'::jsonb) on conflict(kind,id) do nothing;
insert into public.training_knowledge(id,kind,version,content) values('zero-aim','competency','2026-10-10.1','{"id":"zero-aim","category":"zero","subcategory":"Combate","title":"Construção Zero: mira","mode":"zero","definition":"Alinhar disparos usando coberturas e janelas de exposição existentes.","context":"Luta sem construção de estruturas.","example":"Separar precisão isolada da escolha do momento de atirar.","evidence_ids":["editorial"],"classification":"editorial"}'::jsonb) on conflict(kind,id) do nothing;
insert into public.training_knowledge(id,kind,version,content) values('zero-movement','competency','2026-10-10.1','{"id":"zero-movement","category":"zero","subcategory":"Movimento","title":"Construção Zero: movimentação","mode":"zero","definition":"Coordenar deslocamento com proteção e rotas de fuga.","context":"Travessia sem criar cobertura por construção.","example":"Revisar um trajeto exposto e a alternativa disponível.","evidence_ids":["editorial"],"classification":"editorial"}'::jsonb) on conflict(kind,id) do nothing;
insert into public.training_knowledge(id,kind,version,content) values('zero-cover','competency','2026-10-10.1','{"id":"zero-cover","category":"zero","subcategory":"Proteção","title":"Uso de cobertura","mode":"zero","definition":"Usar terreno e objetos para limitar linhas de tiro adversárias.","context":"Preparação e saída de uma troca.","example":"Identificar a próxima cobertura antes de abandonar a atual.","evidence_ids":["editorial"],"classification":"editorial"}'::jsonb) on conflict(kind,id) do nothing;
insert into public.training_knowledge(id,kind,version,content) values('zero-position','competency','2026-10-10.1','{"id":"zero-position","category":"zero","subcategory":"Posição","title":"Construção Zero: posicionamento","mode":"zero","definition":"Escolher posição pelo terreno, linhas de visão e saída disponível.","context":"Espera, combate e zona.","example":"Comparar duas posições naturais sem propor construir uma box.","evidence_ids":["editorial"],"classification":"editorial"}'::jsonb) on conflict(kind,id) do nothing;
insert into public.training_knowledge(id,kind,version,content) values('zero-rotation','competency','2026-10-10.1','{"id":"zero-rotation","category":"zero","subcategory":"Rotação","title":"Construção Zero: rotação","mode":"zero","definition":"Planejar travessia usando terreno, mobilidade disponível e informação.","context":"Zona fechando sem proteção construída.","example":"Registrar trechos expostos e opções de recuo.","evidence_ids":["editorial"],"classification":"editorial"}'::jsonb) on conflict(kind,id) do nothing;
insert into public.training_knowledge(id,kind,version,content) values('zero-endgame','competency','2026-10-10.1','{"id":"zero-endgame","category":"zero","subcategory":"Fim de partida","title":"Construção Zero: Endgame","mode":"zero","definition":"Combinar terreno, mobilidade e informação na zona final.","context":"Poucas coberturas e decisões sob pressão.","example":"Revisar uma movimentação sem recomendar tarping ou edição.","evidence_ids":["editorial"],"classification":"editorial"}'::jsonb) on conflict(kind,id) do nothing;
insert into public.training_knowledge(id,kind,version,content) values('zero-awareness','competency','2026-10-10.1','{"id":"zero-awareness","category":"zero","subcategory":"Informação","title":"Percepção de ameaças","mode":"zero","definition":"Atualizar ameaças observadas e possíveis linhas de tiro.","context":"Trocas com mais de um adversário.","example":"Anotar a pista visual ou sonora que justificou a mudança de alvo.","evidence_ids":["editorial"],"classification":"editorial"}'::jsonb) on conflict(kind,id) do nothing;
insert into public.training_knowledge(id,kind,version,content) values('zero-resources','competency','2026-10-10.1','{"id":"zero-resources","category":"zero","subcategory":"Recursos","title":"Construção Zero: recursos","mode":"zero","definition":"Planejar munição, cura e mobilidade segundo a situação.","context":"Preparação para atravessar ou combater.","example":"Registrar consumo de mobilidade e o recurso disponível depois.","evidence_ids":["editorial"],"classification":"editorial"}'::jsonb) on conflict(kind,id) do nothing;
insert into public.training_knowledge(id,kind,version,content) values('baseline','principle','2026-10-10.1','{"id":"baseline","title":"Avaliar antes de prescrever","body":"Escolha um cenário e registre configuração, erro observado e resultado inicial. Não transforme um único teste em diagnóstico de habilidade.","evidence_ids":["motor-review","editorial","deliberate-meta"]}'::jsonb) on conflict(kind,id) do nothing;
insert into public.training_knowledge(id,kind,version,content) values('purpose','principle','2026-10-10.1','{"id":"purpose","title":"Separar a finalidade da sessão","body":"Aquecimento prepara para jogar; treino técnico trabalha uma dificuldade; prática contextual testa decisões contra oposição; revisão interpreta os registros. Uma atividade pode cumprir finalidades diferentes conforme o objetivo.","evidence_ids":["khanada","editorial"]}'::jsonb) on conflict(kind,id) do nothing;
insert into public.training_knowledge(id,kind,version,content) values('spacing','principle','2026-10-10.1','{"id":"spacing","title":"Distribuir conforme a vida real","body":"Organize oportunidades de prática que caibam na agenda e preservem recuperação. Não existe quantidade de minutos validada aqui como ideal para Fortnite.","evidence_ids":["spacing","sleep","editorial"]}'::jsonb) on conflict(kind,id) do nothing;
insert into public.training_knowledge(id,kind,version,content) values('variation','principle','2026-10-10.1','{"id":"variation","title":"Variar com uma pergunta","body":"Comece com condições estáveis para entender o erro. Quando fizer sentido, varie uma condição e teste aplicação. Alternância aleatória não é superior em todos os contextos.","evidence_ids":["variability","editorial"]}'::jsonb) on conflict(kind,id) do nothing;
insert into public.training_knowledge(id,kind,version,content) values('transfer','principle','2026-10-10.1','{"id":"transfer","title":"Distinguir teste, retenção e aplicação","body":"Melhor resultado no mesmo bloco pode ser adaptação momentânea. Reavalie em outra sessão e observe a habilidade em partidas, registrando diferenças de cenário.","evidence_ids":["motor-review","variability","editorial","perception"]}'::jsonb) on conflict(kind,id) do nothing;
insert into public.training_knowledge(id,kind,version,content) values('feedback','principle','2026-10-10.1','{"id":"feedback","title":"Feedback específico e verificável","body":"Descreva o que ocorreu, a informação disponível e uma alternativa. Teste uma pista de atenção por vez e não imponha um foco universal.","evidence_ids":["attention-bias","editorial","feedback-children","deliberate-debate"]}'::jsonb) on conflict(kind,id) do nothing;
insert into public.training_knowledge(id,kind,version,content) values('recovery','principle','2026-10-10.1','{"id":"recovery","title":"Recuperação faz parte do planejamento","body":"Permita reduzir ou encerrar uma sessão por desconforto ou falta de concentração. Variação de resultado não identifica sua causa nem diagnostica fadiga. Sono, movimento e conforto merecem espaço fora do jogo.","evidence_ids":["exercise-review","sleep","ergonomics","editorial","fatigue"]}'::jsonb) on conflict(kind,id) do nothing;
insert into public.training_knowledge(id,kind,version,content) values('opposition','principle','2026-10-10.1','{"id":"opposition","title":"Escolher a oposição pelo objetivo","body":"1v1 ajuda a repetir situações; duplas permitem revisar comunicação; scrims e ranqueadas oferecem contextos distintos. Registre regras e recursos para entender o que cada sessão realmente representou.","evidence_ids":["jivan-duel","vital","khanada","editorial"]}'::jsonb) on conflict(kind,id) do nothing;
insert into public.training_knowledge(id,kind,version,content) values('adapt','principle','2026-10-10.1','{"id":"adapt","title":"Ajustar com evidência local","body":"Revise exemplos e contraexemplos, escolha a próxima prioridade e mantenha o histórico. Uma mudança de meta exige revalidar cenário e regras, sem apagar resultados anteriores.","evidence_ids":["editorial"]}'::jsonb) on conflict(kind,id) do nothing;
insert into public.training_knowledge(id,kind,version,content) values('mechanics-foundation','path','2026-10-10.1','{"id":"mechanics-foundation","title":"Controle antes de velocidade","mode":"build","level":"beginner","objective":"Identificar uma interrupção de edição e verificar se reaparece em combate.","exercise_ids":["00000000-0000-4000-8000-000000001001","00000000-0000-4000-8000-000000001002","00000000-0000-4000-8000-000000001004","00000000-0000-4000-8000-000000001006"],"competency_ids":["freebuild","editing","box-fight","self-review"],"progression":"Avance pela consistência do procedimento e pelo erro observado, sem um limiar universal de acertos.","evidence_ids":["motor-review","editorial"]}'::jsonb) on conflict(kind,id) do nothing;
insert into public.training_knowledge(id,kind,version,content) values('piece-to-fight','path','2026-10-10.1','{"id":"piece-to-fight","title":"Piece Control aplicado","mode":"build","level":"intermediate","objective":"Relacionar controle de peças, exposição e decisão de finalizar.","exercise_ids":["00000000-0000-4000-8000-000000001003","00000000-0000-4000-8000-000000001016","00000000-0000-4000-8000-000000001004","00000000-0000-4000-8000-000000001006"],"competency_ids":["piece-ownership","peek","box-fight"],"progression":"Compare tentativas isoladas com episódios contra adversário, preservando a diferença entre os contextos.","evidence_ids":["jivan-piece","editorial"]}'::jsonb) on conflict(kind,id) do nothing;
insert into public.training_knowledge(id,kind,version,content) values('endgame-decisions','path','2026-10-10.1','{"id":"endgame-decisions","title":"Endgame com uma pergunta","mode":"build","level":"intermediate","objective":"Revisar como cobertura e recursos influenciam uma rotação.","exercise_ids":["00000000-0000-4000-8000-000000001019","00000000-0000-4000-8000-000000001018","00000000-0000-4000-8000-000000001005","00000000-0000-4000-8000-000000001021"],"competency_ids":["rotation","tarping","moving-zone","refresh"],"progression":"Teste uma alternativa na próxima oportunidade e registre também casos em que ela não ajudou.","evidence_ids":["jivan-zone","editorial"]}'::jsonb) on conflict(kind,id) do nothing;
insert into public.training_knowledge(id,kind,version,content) values('zero-cover','path','2026-10-10.1','{"id":"zero-cover","title":"Construção Zero: terreno e decisão","mode":"zero","level":"beginner","objective":"Identificar uma saída protegida antes de aceitar uma troca.","exercise_ids":["00000000-0000-4000-8000-000000001024","00000000-0000-4000-8000-000000001025","00000000-0000-4000-8000-000000001006"],"competency_ids":["zero-cover","zero-position","zero-endgame","self-review"],"progression":"Reavalie em partidas distintas. Nenhuma etapa depende de construção, edição ou Piece Control.","evidence_ids":["editorial"]}'::jsonb) on conflict(kind,id) do nothing;
insert into public.training_knowledge(id,kind,version,content) values('short-review','path','2026-10-10.1','{"id":"short-review","title":"Sessão curta de análise","mode":"both","level":"beginner","objective":"Transformar um episódio em uma hipótese testável.","exercise_ids":["00000000-0000-4000-8000-000000001006","00000000-0000-4000-8000-000000001022"],"competency_ids":["self-review","offspawn"],"progression":"Escolha apenas um episódio se o tempo disponível for curto. Quantidade de revisões não mede qualidade da decisão.","evidence_ids":["khanada","editorial"]}'::jsonb) on conflict(kind,id) do nothing;
insert into public.exercises(id,title,creator,map_code,category,categories,tags,skills,mode,level,description,instructions,metric,source_url,verified_at,published,research,measurement) values('00000000-0000-4000-8000-000000001101','1v1 com objetivo de troca','jivantv','1907-3111-7836','competitive',ARRAY['combat','competitive'],ARRAY['duel','realistic','trades'],ARRAY['duel','realistic','trades'],'build','intermediate','Aplicar uma pergunta específica contra oposição e revisar decisões com contexto, sem uma nota universal de habilidade.','Combine um objetivo com o adversário e selecione um dos modos disponíveis no ALL IN ONE [1v1]. Registre modo, recursos e versão. Após as rodadas, revise uma troca favorável e uma desfavorável com base na exposição e nas alternativas.','Decisões revisadas (volume, não qualidade)','https://www.fortnite.com/@jivantv/1907-3111-7836','2026-10-10T03:00:00Z',true,'{"competency_ids":["duel","realistic","trades"],"evidence_ids":["editorial","jivan-duel"],"purpose":"contextual","completion":"Registrar duas trocas com contexto e uma alternativa para testar; confirmar conclusão manualmente.","transfer":"Compare a decisão observada com outra oportunidade em uma partida. Preserve contexto e regras; não atribua evolução à simples contagem de sessões.","limitations":"Atividade editorial, sem eficácia experimental estabelecida. Participação depende das regras da plataforma ou comunidade. Sem matchmaking próprio ou teste dentro do Fortnite.","review_status":"verified","review_due_at":"2026-11-10T00:00:00Z","review_notes":"Fonte e finalidade revisadas. Não houve execução no jogo nem validação de resultados."}'::jsonb,'{"unit":"decisões revisadas","min":0,"max":1000,"direction":"higher","procedure":"Registrar apenas episódios efetivamente revisados. Contagem indica volume de análise; comparar decisões exige contexto e não implica melhor habilidade.","version":"clutchfolio-research-1"}'::jsonb) on conflict(id) do nothing;
insert into public.exercises(id,title,creator,map_code,category,categories,tags,skills,mode,level,description,instructions,metric,source_url,verified_at,published,research,measurement) values('00000000-0000-4000-8000-000000001102','Duo Practice: revisão de comunicação','Clutchfolio · protocolo editorial',NULL,'vod',ARRAY['vod','competitive'],ARRAY['duo','information','self-review'],ARRAY['duo','information','self-review'],'both','intermediate','Aplicar uma pergunta específica contra oposição e revisar decisões com contexto, sem uma nota universal de habilidade.','Escolha uma gravação própria de uma partida em dupla. Com consentimento do parceiro, revise uma chamada: informação disponível, instrução, entendimento e execução. Não envie áudio privado de terceiros à plataforma. Anote uma forma mais clara de comunicar.','Decisões revisadas (volume, não qualidade)','https://github.com/sallumm/fortnite-competitive-platform/blob/feat/training-research/docs/research/TRAINING_METHODOLOGY.md','2026-10-10T03:00:00Z',true,'{"competency_ids":["duo","information","self-review"],"evidence_ids":["editorial"],"purpose":"review","completion":"Registrar uma chamada, a resposta observada e uma alternativa acordada; não é obrigatório armazenar áudio.","transfer":"Compare a decisão observada com outra oportunidade em uma partida. Preserve contexto e regras; não atribua evolução à simples contagem de sessões.","limitations":"Atividade editorial, sem eficácia experimental estabelecida. Participação depende das regras da plataforma ou comunidade. Sem matchmaking próprio ou teste dentro do Fortnite.","review_status":"verified","review_due_at":"2026-11-10T00:00:00Z","review_notes":"Fonte e finalidade revisadas. Não houve execução no jogo nem validação de resultados."}'::jsonb,'{"unit":"decisões revisadas","min":0,"max":1000,"direction":"higher","procedure":"Registrar apenas episódios efetivamente revisados. Contagem indica volume de análise; comparar decisões exige contexto e não implica melhor habilidade.","version":"clutchfolio-research-1"}'::jsonb) on conflict(id) do nothing;
insert into public.exercises(id,title,creator,map_code,category,categories,tags,skills,mode,level,description,instructions,metric,source_url,verified_at,published,research,measurement) values('00000000-0000-4000-8000-000000001103','Scrims: objetivo e debrief','Clutchfolio · protocolo editorial',NULL,'competitive',ARRAY['vod','competitive'],ARRAY['scrims','rotation','self-review'],ARRAY['scrims','rotation','self-review'],'both','intermediate','Aplicar uma pergunta específica contra oposição e revisar decisões com contexto, sem uma nota universal de habilidade.','Consulte as regras e requisitos do organizador antes de entrar. Escolha um objetivo de rotação para a sessão. Registre região, regras especiais e contexto; depois revise um episódio. A plataforma não inscreve você em salas nem promete disponibilidade.','Decisões revisadas (volume, não qualidade)','https://vitalscrims.com/','2026-10-10T03:00:00Z',true,'{"competency_ids":["scrims","rotation","self-review"],"evidence_ids":["editorial","vital"],"purpose":"competitive","completion":"Registrar regras consultadas, objetivo e um episódio revisado após a partida.","transfer":"Compare a decisão observada com outra oportunidade em uma partida. Preserve contexto e regras; não atribua evolução à simples contagem de sessões.","limitations":"Atividade editorial, sem eficácia experimental estabelecida. Participação depende das regras da plataforma ou comunidade. Sem matchmaking próprio ou teste dentro do Fortnite.","review_status":"verified","review_due_at":"2026-11-10T00:00:00Z","review_notes":"Fonte e finalidade revisadas. Não houve execução no jogo nem validação de resultados."}'::jsonb,'{"unit":"decisões revisadas","min":0,"max":1000,"direction":"higher","procedure":"Registrar apenas episódios efetivamente revisados. Contagem indica volume de análise; comparar decisões exige contexto e não implica melhor habilidade.","version":"clutchfolio-research-1"}'::jsonb) on conflict(id) do nothing;
insert into public.exercises(id,title,creator,map_code,category,categories,tags,skills,mode,level,description,instructions,metric,source_url,verified_at,published,research,measurement) values('00000000-0000-4000-8000-000000001104','Ranqueada: testar uma decisão','Clutchfolio · protocolo editorial',NULL,'competitive',ARRAY['vod','competitive'],ARRAY['ranked','fight-selection','self-review'],ARRAY['ranked','fight-selection','self-review'],'both','intermediate','Aplicar uma pergunta específica contra oposição e revisar decisões com contexto, sem uma nota universal de habilidade.','Em uma partida ranqueada disponível na sua modalidade, escolha uma pergunta sobre aceitar ou evitar lutas. Após a partida, registre uma decisão com informação disponível, alternativa e resultado. Rank e eliminações não substituem a análise da decisão.','Decisões revisadas (volume, não qualidade)','https://github.com/sallumm/fortnite-competitive-platform/blob/feat/training-research/docs/research/TRAINING_METHODOLOGY.md','2026-10-10T03:00:00Z',true,'{"competency_ids":["ranked","fight-selection","self-review"],"evidence_ids":["editorial"],"purpose":"competitive","completion":"Revisar uma decisão real e indicar uma próxima hipótese, mesmo quando o resultado da partida foi desfavorável.","transfer":"Compare a decisão observada com outra oportunidade em uma partida. Preserve contexto e regras; não atribua evolução à simples contagem de sessões.","limitations":"Atividade editorial, sem eficácia experimental estabelecida. Participação depende das regras da plataforma ou comunidade. Sem matchmaking próprio ou teste dentro do Fortnite.","review_status":"verified","review_due_at":"2026-11-10T00:00:00Z","review_notes":"Fonte e finalidade revisadas. Não houve execução no jogo nem validação de resultados."}'::jsonb,'{"unit":"decisões revisadas","min":0,"max":1000,"direction":"higher","procedure":"Registrar apenas episódios efetivamente revisados. Contagem indica volume de análise; comparar decisões exige contexto e não implica melhor habilidade.","version":"clutchfolio-research-1"}'::jsonb) on conflict(id) do nothing;
